"""Read local peak and RMS levels generated by meter.py; no audio is sent to the bar."""
import json
from pathlib import Path
from serve import page
INTERVAL=.3
def snapshot(o,m):
    data=json.loads(Path(o["levels_file"]).expanduser().read_text());peak=data["peak_db"];held=data["held_db"]
    def level(n):return "silence" if n is None else f"{n:.1f}dB"
    return dict(state="Local PCM meter",key=str(bool(data["clipped"])),alert=data["clipped"],pages=[
        page("PEAK HEADROOM",("--" if peak is None else f"{max(0,-peak):.1f}dB"),"Peak "+level(peak),"Maximum "+level(held),fraction=0 if peak is None else (peak+48)/48),
        page("PEAK HOLD",level(held),"Clipped samples "+str(data["clipped"]),"Reset on meter restart"),
        page("RMS LEVEL",level(data["rms_db"]),"dBFS / mono 16-bit","No waveform leaves host")])
